import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { runChecks } from "../../../src/core/doctor";
import { install } from "../../../src/core/hooks";
import { assertInstallable, detect } from "../../../src/core/precommit";

const vs = { exclude: [], enable: [], disable: [], noGitCheck: false, customRules: [], customProfiles: {} };
const FRAMEWORK_HOOK = [
    "#!/usr/bin/env bash",
    "# File generated by pre-commit: https://pre-commit.com",
    "# ID: 138fd403232d2ddd5efb44317e38bf03",
    'exec pre-commit "${ARGS[@]}"',
    "",
].join("\n");
let root;

const hook = (stage) => path.join(root, ".git", "hooks", stage);
const writeHook = (stage, text) => {
    fs.mkdirSync(path.dirname(hook(stage)), { recursive: true });
    fs.writeFileSync(hook(stage), text);
};

beforeEach(() => {
    root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "sweepito-pc-")));
    execFileSync("git", ["-C", root, "init", "-q"]);
});

afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

describe("detect", () => {
    it("reports nothing in a plain repository", async () => {
        expect(await detect(root)).toMatchObject({
            configFile: null,
            configured: false,
            managed: { "post-commit": false, "pre-commit": false },
        });
    });

    it("sees Sweepito in the config and hooks generated by the framework", async () => {
        fs.writeFileSync(
            path.join(root, ".pre-commit-config.yaml"),
            "repos:\n  - repo: https://github.com/coldsofttech/Sweepito\n    rev: v0.2.0\n    hooks:\n      - id: sweepito-clean\n",
        );
        writeHook("post-commit", FRAMEWORK_HOOK);
        const found = await detect(root);
        expect(found.configured).toBe(true);
        expect(found.managed).toEqual({ "post-commit": true, "pre-commit": false });
        expect(found.shadowed["post-commit"]).toBe(false);
    });

    it("does not count a config that does not mention Sweepito", async () => {
        fs.writeFileSync(path.join(root, ".pre-commit-config.yaml"), "repos:\n  - repo: https://example.com/other\n");
        expect((await detect(root)).configured).toBe(false);
    });
});

describe("installing over a framework hook", () => {
    it("is refused, because the appended block would never run", async () => {
        writeHook("post-commit", FRAMEWORK_HOOK);
        await expect(assertInstallable(root, "post-commit")).rejects.toThrow(/ends with exec/);
        await expect(assertInstallable(root, "pre-commit")).resolves.toBeUndefined();
    });

    it("doctor flags a block that is shadowed by the framework's exec", async () => {
        writeHook("post-commit", FRAMEWORK_HOOK);
        await install(root, "post-commit"); // what the CLI would do
        expect((await detect(root)).shadowed["post-commit"]).toBe(true);
        const check = (await runChecks(root, vs)).find((c) => c.name === "pre-commit framework");
        expect(check).toMatchObject({ ok: false, required: false });
        expect(check.detail).toContain("never runs");
    });

    it("doctor stays quiet when the framework is not used", async () => {
        expect((await runChecks(root, vs)).some((c) => c.name === "pre-commit framework")).toBe(false);
    });
});
